<script setup>
import AdminNavigation from '@/Components/Admin/AdminNavigation.vue';
import DashboardChart from '@/Components/Admin/DashboardChart.vue';
import PortalLayout from '@/Layouts/PortalLayout.vue';
import { Head, Link, router } from '@inertiajs/vue3';
import { reactive } from 'vue';
const props = defineProps({ metrics: Object, productMetrics: Array, charts: Object, filters: Object });
const filter = reactive({ ...props.filters });
const currency = (value) => new Intl.NumberFormat('en-NG', { style: 'currency', currency: 'NGN', maximumFractionDigits: 0 }).format(value);
const number = (value) => Number(value).toLocaleString();
const applyFilters = () => router.get(route('admin.dashboard'), filter, { preserveState: true, replace: true });
const operationalCards = [['Total Customers','totalCustomers','admin.customers.index',''],['Active Customers','activeCustomers','admin.customers.index','status=active'],['Active Subscriptions','activeSubscriptions','admin.customers.index',''],['Trials','trials','admin.customers.index',''],['Active Licenses','activeLicenses','admin.customers.index',''],['Expired Licenses','expiredLicenses','admin.customers.index',''],['Outstanding Invoices','outstandingInvoices','admin.invoices.index',''],['Pending Payments','pendingPayments','admin.payments.index','status=pending'],['Open Support Tickets','openSupportTickets','admin.support.index','']];
const salesCards = [['New leads','newLeads'],['Demo requests','demoRequests'],['Demo completed','demoCompleted'],['Quotation conversion','quotationConversion'],['Won deals','wonDeals']];
</script>
<template>
<Head title="Executive dashboard"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="overview"/><Link :href="route('dashboard')" class="block rounded-lg px-3 py-2 text-slate-600 hover:bg-slate-50">Customer portal</Link></template><main>
<div class="flex flex-col gap-5 xl:flex-row xl:items-end xl:justify-between"><div><p class="text-sm font-semibold uppercase tracking-wider text-cyan-700">Executive overview</p><h1 class="mt-2 text-3xl font-bold text-slate-900">Business performance</h1><p class="mt-2 text-slate-600">Commercial, customer, product, and service health in one view.</p></div><form class="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-4" @submit.prevent="applyFilters"><label class="text-xs font-semibold text-slate-600">Period<select v-model="filter.range" class="mt-1 block w-full rounded-lg border-slate-300 text-sm"><option value="30_days">Last 30 days</option><option value="quarter">This quarter</option><option value="year">This year</option><option value="custom">Custom</option></select></label><label class="text-xs font-semibold text-slate-600">From<input v-model="filter.from" type="date" :disabled="filter.range!=='custom'" class="mt-1 block w-full rounded-lg border-slate-300 text-sm disabled:bg-slate-100"/></label><label class="text-xs font-semibold text-slate-600">To<input v-model="filter.to" type="date" :disabled="filter.range!=='custom'" class="mt-1 block w-full rounded-lg border-slate-300 text-sm disabled:bg-slate-100"/></label><button class="self-end rounded-lg bg-[#0B3D6E] px-4 py-2.5 text-sm font-semibold text-white">Apply</button></form></div>
<section class="mt-8"><h2 class="text-lg font-bold text-slate-900">Operations</h2><div class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-5"><Link v-for="card in operationalCards" :key="card[1]" :href="card[3]?`${route(card[2])}?${card[3]}`:route(card[2])" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:border-cyan-300"><p class="text-sm text-slate-500">{{ card[0] }}</p><p class="mt-2 text-3xl font-bold text-[#0B3D6E]">{{ number(metrics[card[1]]) }}</p></Link></div></section>
<section class="mt-8"><h2 class="text-lg font-bold text-slate-900">Revenue</h2><div class="mt-4 grid gap-4 md:grid-cols-3"><article v-for="item in [['Revenue this month','revenueThisMonth'],['Revenue this year','revenueThisYear'],['Outstanding receivables','outstandingReceivables']]" :key="item[1]" class="rounded-2xl bg-gradient-to-br from-[#071426] to-[#0B3D6E] p-6 text-white shadow-sm"><p class="text-sm text-cyan-100">{{ item[0] }}</p><p class="mt-3 text-3xl font-bold">{{ currency(metrics[item[1]]) }}</p></article></div></section>
<section class="mt-8"><h2 class="text-lg font-bold text-slate-900">Products</h2><div class="mt-4 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article v-for="product in productMetrics" :key="product.code" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="font-semibold text-slate-900">{{ product.name }}</p><p class="mt-2 text-3xl font-bold text-[#0797A5]">{{ number(product.customers) }}</p><p class="text-sm text-slate-500">customers</p></article></div></section>
<section class="mt-8"><h2 class="text-lg font-bold text-slate-900">Sales activity <span class="text-sm font-normal text-slate-500">({{ filters.from }} – {{ filters.to }})</span></h2><div class="mt-4 grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><article v-for="item in salesCards" :key="item[1]" class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">{{ item[0] }}</p><p class="mt-2 text-3xl font-bold text-slate-900">{{ number(metrics[item[1]]) }}{{ item[1]==='quotationConversion'?'%':'' }}</p></article></div></section>
<section class="mt-8 grid gap-5 xl:grid-cols-2"><DashboardChart title="Monthly revenue" :data="charts.monthlyRevenue" type="line" :value-label="currency"/><DashboardChart title="Customer growth" :data="charts.customerGrowth" type="line" :value-label="number"/><DashboardChart title="Subscriptions by product" :data="charts.subscriptionsByProduct" :value-label="number"/><DashboardChart title="Leads by status" :data="charts.leadsByStatus" type="doughnut" :value-label="number"/><DashboardChart title="Invoice status" :data="charts.invoiceStatus" type="doughnut" :value-label="number"/></section>
</main></PortalLayout>
</template>
